    g.fillRect(0, 0, 128, 128);
    g.fillStyle = hot ? "#1f4fa8" : "#4a5562";
    g.font = "600 25px 'Barlow Condensed', 'Arial Narrow', sans-serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
